/// <summary>
/// Finds or creates UnitOfMeasure record by Nieda Unit record
/// </summary>
/// <param name = "_record">Niedax Unit record </param>
/// <returns>UnitOfMeasureTranslation record</returns>
static public NDXUtilitasData findOrCreateByObject(Niedax.Utilitas.UtilitasDataContract _record)
{
    NDXUtilitasData lNDXUtilitasData;
    NDXUtilitasDataKeyWords lNDXUtilitasDataKeyWords;
    NDXUtilitasDataSearchCriteria lNDXUtilitasDataSearchCriteria;

    List list;
    ListEnumerator listEnumerator;

    str listObjectValue;

    System.Collections.IEnumerable dotNETList;
    System.Collections.IEnumerator dotNETListEnumerator;
    Niedax.Utilitas.UtilitasDataContractETIM etim;

    Niedax.Utilitas.UtilitasDataContract relatedItem;

    if(_record != null)
    {
        lNDXUtilitasData = NDXUtilitasData::find(_record.ItemId, true);

        if(!lNDXUtilitasData)
        {
            lNDXUtilitasData.ItemId = _record.ItemId;
            lNDXUtilitasData.Company = _record.Company;
            lNDXUtilitasData.insert();
        }

        lNDXUtilitasData.InventTableRefRecId = _record.InventTableRecId;
        lNDXUtilitasData.EAN = _record.EAN;
        lNDXUtilitasData.ModelNumber = _record.Modelnumber;
        lNDXUtilitasData.ProductName1 = _record.ItemName;
        lNDXUtilitasData.ProductName2 = _record.ItemName2;

        lNDXUtilitasData.SearchName = _record.ItemNameAlias;
        lNDXUtilitasData.GoodsId = _record.GoodsID;

        lNDXUtilitasData.GrossDepthNew = _record.GrossLenght;
        lNDXUtilitasData.GrossWidthNew = _record.GrossWidth;
        lNDXUtilitasData.GrossHeightNew = _record.GrossHeight;

        lNDXUtilitasData.NominalSizeDepth = _record.Length;
        lNDXUtilitasData.NominalSizeWidth = _record.Width;
        lNDXUtilitasData.NominalSizeHeight = _record.Height;

        lNDXUtilitasData.ItemCategory = _record.ItemGroup;
        lNDXUtilitasData.ItemDescription = _record.ItemDescription;
        lNDXUtilitasData.TransferBegin = _record.TransferBegin;

        ttsbegin;
        lNDXUtilitasData.doUpdate();
        ttscommit;

        list = strSplit(_record.KeyWords, ';');

        if(list != null)
        {
            //Delete before fill
            delete_from lNDXUtilitasDataKeyWords
                where lNDXUtilitasDataKeyWords.NDXUtilitasDataRefRecId == lNDXUtilitasData.RecId;

            listEnumerator = list.getEnumerator();

            while(listEnumerator.MoveNext())
            {
                listObjectValue = listEnumerator.current();
                NDXUtilitasDataKeyWords::findOrCreateByObject(lNDXUtilitasData.RecId , listObjectValue);
            }
        }

        list = strSplit(_record.OPKSearchCriteria, ';');

        if(list != null)
        {
            //Delete before fill
            delete_from lNDXUtilitasDataSearchCriteria
                where lNDXUtilitasDataSearchCriteria.NDXUtilitasDataRefRecId == lNDXUtilitasData.RecId;

            listEnumerator = list.getEnumerator();

            while(listEnumerator.MoveNext())
            {
                listObjectValue = listEnumerator.current();
                NDXUtilitasDataSearchCriteria::findOrCreateByObject(lNDXUtilitasData.RecId , listObjectValue);
            }
        }

        //ETIM
        dotNETList = _record.Etim;
        dotNETListEnumerator = dotNETList.GetEnumerator();

        while(dotNETListEnumerator.MoveNext())
        {
            etim = dotNETListEnumerator.Current;
            NDXUtilitasDataETIM::findOrCreateByObject(lNDXUtilitasData.RecId, etim);
        }

        //Related Products

        dotNETList = _record.RelatedItems;
        dotNETListEnumerator = dotNETList.GetEnumerator();

        while(dotNETListEnumerator.MoveNext())
        {
            relatedItem = dotNETListEnumerator.Current;
            NDXUtilitasDataRelatedItems::findOrCreateByObject(lNDXUtilitasData.RecId, relatedItem);
        }
    }

    return lNDXUtilitasData;
}

/// <summary>
/// find NDXUtilitasData record
/// </summary>
/// <param name = "_itemId">item id</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>NDXUtilitasData record</returns>
static public NDXUtilitasData find(ItemId _itemId, boolean _forUpdate = false)
{
    NDXUtilitasData lNDXUtilitasData;

    lNDXUtilitasData.selectForUpdate(_forUpdate);

    select lNDXUtilitasData
        where lNDXUtilitasData.ItemId == _itemId;

    return lNDXUtilitasData;
}
